from pathlib import Path
import json,base64,subprocess,os,hashlib
PAYLOAD={'Program.cs': '', 'RepairNative24.csproj': ''}

w=Path('/workspaces/GodsPVZ-native24-codespace');dst=Path('/tmp/godspvz-native24-codespace-2026-10-01');old=Path('/workspaces/GodsPVZ-native19')
project=w/'scripts/takeover/native24/RepairNative24';project.mkdir(exist_ok=True)
for n,b in PAYLOAD.items():(project/n).write_bytes(base64.b64decode(b))
summary={'runs':[],'source_hashes':{n:hashlib.sha256((project/n).read_bytes()).hexdigest() for n in PAYLOAD}}
bin=dst/'patcher-bin';bin.mkdir(exist_ok=True)
cecil=old/'Tools/Stage9Native4Recovery/tools/lib/netstandard2.0/Mono.Cecil.dll'
def run(args,name,**kw):
 with (dst/(name+'.log')).open('w') as f:r=subprocess.run(args,stdout=f,stderr=subprocess.STDOUT,**kw)
 summary['runs'].append({'argv':args,'exit':r.returncode,'log':str(dst/(name+'.log')),'tail':(dst/(name+'.log')).read_text()[-4000:]})
 if r.returncode:
  print(json.dumps(summary,indent=2));raise SystemExit(r.returncode)
run(['dotnet','build',str(project/'RepairNative24.csproj'),'-c','Release','-o',str(bin),'-p:MonoCecilPath='+str(cecil)],'patcher-build')
run(['dotnet',str(bin/'RepairNative24.dll'),'--self-test',str(dst/'patcher-controls.json')],'patcher-controls')
env=dict(os.environ,GODSPVZ_RESOLVER=str(old/'.validation/native23-independent-full-review/baseline/managed'))
for repeat in [1,2]:
 output=dst/f'candidate-{repeat}.dll'
 assert not output.exists(),str(output)
 run(['dotnet',str(bin/'RepairNative24.dll'),str(dst/'inputs/baseline.dll'),str(output),str(dst/'inputs/edits-batch1.json'),str(dst/f'patch-report-{repeat}.json')],f'patch-{repeat}',env=env)
summary['hashes']={str(f.name):hashlib.sha256(f.read_bytes()).hexdigest() for f in [dst/'inputs/baseline.dll',dst/'review/batch1.dll',dst/'candidate-1.dll',dst/'candidate-2.dll']}
summary['deterministic']=summary['hashes']['candidate-1.dll']==summary['hashes']['candidate-2.dll']
summary['matches_historical']=summary['hashes']['candidate-1.dll']==summary['hashes']['batch1.dll']
for tag,source in [('baseline',dst/'inputs/baseline.dll'),('historical',dst/'review/batch1.dll'),('candidate',dst/'candidate-1.dll')]:
 run(['dotnet',str(old/'.validation/native23-independent-full-review/inspector-bin/Inspector.dll'),str(source),str(dst/f'{tag}-metadata.json')],f'inspect-{tag}')
(dst/'patcher-summary.json').write_text(json.dumps(summary,indent=2));print(json.dumps(summary,indent=2))
